const express = require('express');
const rateLimit = require('express-rate-limit');
const { asyncHandler } = require('../middleware/errorHandler');
const { requireWritableNode } = require('../middleware/requireWritableNode');
const logger = require('../utils/logger');
const { trackWebEvent } = require('../services/webAnalyticsService');
const statsService = require('../services/statsService');

const router = express.Router();
const analyticsWriteGuard = requireWritableNode({ routeGroup: 'analytics-write' });
const analyticsWriteMethods = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);

router.use((req, res, next) => {
  if (!analyticsWriteMethods.has(req.method)) return next();
  return analyticsWriteGuard(req, res, next);
});

// Support `navigator.sendBeacon(url, JSON.stringify(payload))` which may arrive as `text/plain`.
// Note: app-level JSON body parsing is already enabled; this only kicks in for non-JSON content-types.
router.use(express.text({ type: ['text/plain', 'text/*'], limit: process.env.ANALYTICS_MAX_BODY_BYTES || '64kb' }));

const ANALYTICS_ENABLED = String(process.env.ANALYTICS_WEB_ENABLED || '').toLowerCase() !== 'false';
const APP_TELEMETRY_ENABLED = String(process.env.ANALYTICS_APP_CLIENT_ENABLED || '').toLowerCase() !== 'false';
const MAX_BODY_BYTES = Math.max(1024, Math.min(parseInt(process.env.ANALYTICS_MAX_BODY_BYTES || '65536', 10) || 65536, 1024 * 1024));
const MAX_EVENTS_PER_BATCH = Math.max(1, Math.min(parseInt(process.env.ANALYTICS_MAX_EVENTS || '50', 10) || 50, 200));
const MAX_METADATA_BYTES = Math.max(256, Math.min(parseInt(process.env.ANALYTICS_MAX_METADATA_BYTES || '8192', 10) || 8192, 1024 * 256));

const UUID_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const clampText = (value, maxLen) => {
  if (value === undefined || value === null) return null;
  const str = String(value).trim();
  if (!str) return null;
  return str.length > maxLen ? str.slice(0, maxLen) : str;
};

const normalizeWebPath = (value) => {
  const raw = clampText(value, 512);
  if (!raw) return null;

  // Accept accidental full URL payloads; canonicalize to pathname + hash (no query string).
  try {
    if (/^https?:\/\//i.test(raw)) {
      const u = new URL(raw);
      return `${u.pathname || '/'}${u.hash || ''}`;
    }
  } catch (_) {
    // fall through
  }

  // Strip query string (keep hash if present).
  const [beforeHash, hashPart] = raw.split('#', 2);
  const base = (beforeHash || '').split('?', 2)[0] || '';
  const normalizedBase = base.startsWith('/') ? base : `/${base}`;
  const hash = hashPart !== undefined ? `#${hashPart}` : '';
  return `${normalizedBase}${hash}`;
};

const safeJsonSize = (value) => {
  try {
    return Buffer.byteLength(JSON.stringify(value || null), 'utf8');
  } catch (_) {
    return null;
  }
};

const parseBody = (req) => {
  // express.json populates objects; express.text populates strings.
  if (req.body && typeof req.body === 'object') return req.body;
  if (typeof req.body !== 'string') return null;
  const raw = req.body.trim();
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (_) {
    return null;
  }
};

const normalizeEventName = (raw) => {
  const name = (raw || '').toString().trim();
  if (!name) return null;
  // Preserve legacy names, but unify cwv -> web_vital.
  if (name === 'cwv') return 'web_vital';
  return name;
};

const allowedEvents = new Set([
  // Core web analytics.
  'page_view',
  'session_start',
  'session_end',
  'section_impression',
  'cta_click',
  'conversion',
  // Forms.
  'form_start',
  'form_submit',
  'form_success',
  'form_error',
  // Quality signals.
  'web_vital',
  'js_error',
]);

const allowedAppEventTypes = new Set([
  'screen_view',
  'screen_duration',
  'onboarding_enter',
  'onboarding_complete',
  'signin_view',
  'signin_attempt',
  'signin_success',
  'signin_failure',
  'signup_view',
  'signup_attempt',
  'signup_success',
  'signup_failure',
  'ar_session_start',
  // First-touch app entry for every visitor, once per session. This is the
  // denominator for direct-acquisition campaigns, which land straight on
  // /register and therefore never emit `guest_app_loaded`.
  'app_entry',
  // Guest entry funnel.
  'guest_app_loaded',
  'guest_map_loaded',
  // Public discovery funnel (supports institutional pilot reporting).
  'map_opened',
  'nearby_discovery_used',
  'artwork_viewed',
  'event_viewed',
  'institution_viewed',
  'route_opened',
  'route_started',
  'route_completed',
  'qr_opened',
  // Contribution funnel.
  'contribution_started',
  'contribution_submitted',
  'artist_profile_created',
  // Institutional funnel.
  'institutional_cta_clicked',
  // Guest -> account activation funnel. Each stage reports only what has
  // actually happened: a registration record is not a session, and a session
  // is not a completed action.
  'protected_action_clicked',
  'auth_gate_viewed',
  'auth_gate_dismissed',
  'auth_method_selected',
  'registration_submitted',
  'email_verification_sent',
  'email_verification_viewed',
  'email_verified',
  'account_session_created',
  'pending_action_restored',
  'pending_action_confirmation_viewed',
  'pending_action_completed',
  'pending_action_failed',
  'first_save_completed',
  'first_follow_completed',
  'first_contribution_completed',
  'activation_prompt_viewed',
  'activation_prompt_dismissed',
  'activation_prompt_accepted',
  'exhibition_viewed',
]);

/// Bounded vocabularies. Anything outside these is dropped rather than stored,
/// so a tampered or buggy client cannot introduce unbounded cardinality into
/// the funnel breakdowns.
const ALLOWED_ACTION_TYPES = new Set([
  'save', 'like', 'follow', 'comment', 'contribute', 'other',
]);

const ALLOWED_TARGET_TYPES = new Set([
  'artwork', 'event', 'exhibition', 'post', 'user', 'marker', 'other',
]);

const ALLOWED_AUTH_METHODS = new Set([
  'google', 'email', 'wallet', 'passkey', 'existing_account',
  'restored_session', 'none',
]);

const ALLOWED_CONTINUATION_STATUS = new Set([
  'restored', 'awaiting_confirmation', 'completed', 'failed',
]);

const ALLOWED_FAILURE_STAGES = new Set([
  'none', 'target_unavailable', 'unauthorized', 'execution', 'expired',
  'network',
]);

const ALLOWED_PROMPT_TRIGGERS = new Set([
  'entity_views', 'dwell', 'return_visit', 'protected_action',
]);

// Campaign landing is a low-cardinality dimension, not an arbitrary URL.
// Keep the historical root/main entries and the two current acquisition
// strategies. Unknown paths still retain the app_entry event, but the route is
// omitted so entity ids, auth paths and attacker-controlled values cannot form
// unbounded breakdown rows.
const ALLOWED_CAMPAIGN_ENTRY_ROUTES = new Set([
  '/', '/main', '/map', '/register',
]);

const APP_PROPERTY_COMPATIBILITY_ALIASES = new Map([
  ['api.kubus.site', ['bapi.kubus.site']],
  ['bapi.kubus.site', ['api.kubus.site']],
]);

const expandAllowedAppProperties = (properties) => {
  const expanded = new Set(properties);
  for (const [source, aliases] of APP_PROPERTY_COMPATIBILITY_ALIASES.entries()) {
    if (!expanded.has(source)) continue;
    for (const alias of aliases) {
      expanded.add(alias);
    }
  }
  return expanded;
};

const allowedAppProperties = expandAllowedAppProperties(new Set(
  (process.env.ANALYTICS_APP_ALLOWED_PROPERTIES || 'app.kubus.site,api.kubus.site,bapi.kubus.site')
    .split(',')
    .map((v) => v.trim())
    .filter(Boolean),
));

const normalizeAppProperty = (value) => {
  const property = clampText(value, 128);
  if (!property) return null;
  return allowedAppProperties.has(property) ? property : null;
};

const sanitizeAppMetadata = (rawMetadata) => {
  const input = rawMetadata && typeof rawMetadata === 'object' ? rawMetadata : {};
  const safe = {};

  const setText = (key, value, maxLen) => {
    const v = clampText(value, maxLen);
    if (v) safe[key] = v;
  };

  const setBool = (key, value) => {
    if (value === true || value === false) safe[key] = value;
  };

  const setInt = (key, value, { min = 0, max = 60 * 60 * 1000 * 24 } = {}) => {
    const n = Number(value);
    if (!Number.isFinite(n)) return;
    const rounded = Math.round(n);
    if (rounded < min || rounded > max) return;
    safe[key] = rounded;
  };

  // Drops anything outside the fixed vocabulary instead of storing it, so a
  // buggy or hostile client cannot blow up breakdown cardinality.
  const setEnum = (key, value, allowed) => {
    const v = clampText(value, 48);
    if (v && allowed.has(v)) safe[key] = v;
  };

  // Landing path only: strip any query/fragment a client might still send and
  // collapse a trailing slash so `/register/` and `/register` are one row.
  const normalizeEntryRoute = (value) => {
    const raw = (value === null || value === undefined) ? '' : value.toString().trim();
    if (!raw) return null;
    const path = raw.split('?')[0].split('#')[0];
    if (!path) return null;
    const prefixed = path.startsWith('/') ? path : `/${path}`;
    const normalized = prefixed.length > 1 && prefixed.endsWith('/')
      ? prefixed.slice(0, -1)
      : prefixed;
    return ALLOWED_CAMPAIGN_ENTRY_ROUTES.has(normalized) ? normalized : null;
  };

  // Required + core fields.
  setText('property', input.property, 128);
  setText('screen_name', input.screen_name, 64);
  setText('screen_route', input.screen_route, 160);
  setText('flow_stage', input.flow_stage, 32);
  setText('method', input.method, 32);
  setText('error_class', input.error_class, 64);
  setText('app_version', input.app_version, 32);
  // Mobile/web build numbers can be date-based (e.g. 202603261), so allow
  // standard 32-bit positive integer range.
  setInt('build_number', input.build_number ?? input.buildNumber, { min: 0, max: 2147483647 });
  setText('platform', input.platform, 24);
  setText('env', input.env, 16);

  // Optional fields.
  setInt('duration_ms', input.duration_ms, { min: 0, max: 1000 * 60 * 60 * 8 });
  setBool('success', input.success);
  setText('onboarding_reason', input.onboarding_reason, 64);
  setBool('truncated', input.truncated);
  setText('locale', input.locale, 16);

  // Campaign attribution. The client has always attached these; until now the
  // sanitiser silently dropped them, so no app event was ever attributable to
  // a campaign. Also hoisted onto the first-class columns below.
  setText('utm_source', input.utm_source, 128);
  setText('utm_medium', input.utm_medium, 128);
  setText('utm_campaign', input.utm_campaign, 160);
  setText('utm_term', input.utm_term, 128);
  setText('utm_content', input.utm_content, 128);
  setText('entry_intent', input.entry_intent, 32);
  setBool('guest', input.guest);
  // Landing surface for the visit (`/register`, `/map`, ...). Stored so app
  // campaigns get the landing-path reporting the marketing side already has.
  // Path only and query-stripped here as well as on the client, so an
  // arbitrary or sensitive query value cannot reach storage through this key.
  setText('entry_route', normalizeEntryRoute(input.entry_route), 120);

  // Activation funnel dimensions, each constrained to a fixed vocabulary.
  setEnum('action_type', input.action_type, ALLOWED_ACTION_TYPES);
  setEnum('target_type', input.target_type, ALLOWED_TARGET_TYPES);
  setEnum('auth_method', input.auth_method, ALLOWED_AUTH_METHODS);
  setEnum('continuation_status', input.continuation_status, ALLOWED_CONTINUATION_STATUS);
  setEnum('failure_stage', input.failure_stage, ALLOWED_FAILURE_STAGES);
  setEnum('prompt_trigger', input.prompt_trigger, ALLOWED_PROMPT_TRIGGERS);
  setText('source_screen', input.source_screen, 64);
  setBool('is_new_account', input.is_new_account);
  setBool('requires_email_verification', input.requires_email_verification);

  // Public-entity ids already emitted by the discovery funnel.
  setText('artwork_id', input.artwork_id, 128);
  setText('event_id', input.event_id, 128);
  setText('exhibition_id', input.exhibition_id, 128);
  setText('institution_id', input.institution_id, 128);
  setText('route_id', input.route_id, 128);
  setText('target_id', input.target_id, 128);
  setText('campaign', input.campaign, 160);
  setText('cta', input.cta, 128);
  setText('kind', input.kind, 32);
  setBool('claimed', input.claimed);

  return safe;
};

/// Extracts the campaign dimensions from sanitised metadata so they can be
/// written to the first-class `analytics_events` columns as well, where the
/// funnel aggregation can index and group on them cheaply.
const campaignColumnsFromMetadata = (metadata) => ({
  utmSource: metadata.utm_source ?? null,
  utmMedium: metadata.utm_medium ?? null,
  utmCampaign: metadata.utm_campaign ?? null,
  utmTerm: metadata.utm_term ?? null,
  utmContent: metadata.utm_content ?? null,
});

const normalizeAppEventPayload = ({ body, rawEvent }) => {
  const eventType = clampText(rawEvent?.event_type ?? rawEvent?.eventType, 64);
  if (!eventType || !allowedAppEventTypes.has(eventType)) {
    const error = new Error('Invalid event_type');
    error.statusCode = 400;
    throw error;
  }

  const eventId = clampText(rawEvent?.event_id ?? rawEvent?.eventId, 64);
  if (!eventId || !UUID_REGEX.test(eventId)) {
    const error = new Error('Invalid event_id');
    error.statusCode = 400;
    throw error;
  }

  const sessionId = clampText(rawEvent?.session_id ?? rawEvent?.sessionId, 64);
  if (!sessionId || !UUID_REGEX.test(sessionId)) {
    const error = new Error('Invalid session_id');
    error.statusCode = 400;
    throw error;
  }

  const actorUserIdRaw = clampText(rawEvent?.actor_user_id ?? rawEvent?.actorUserId, 64);
  const actorUserId = actorUserIdRaw && UUID_REGEX.test(actorUserIdRaw) ? actorUserIdRaw : null;

  const eventTimeRaw = clampText(rawEvent?.event_time ?? rawEvent?.eventTime, 64);
  const eventTime = (() => {
    if (!eventTimeRaw) return null;
    const d = new Date(eventTimeRaw);
    if (Number.isNaN(d.getTime())) return null;
    return d.toISOString();
  })();
  if (!eventTime) {
    const error = new Error('Invalid event_time');
    error.statusCode = 400;
    throw error;
  }

  const property = normalizeAppProperty(
    rawEvent?.metadata?.property ?? rawEvent?.property ?? body?.property ?? body?.site,
  );

  if (!property) {
    const error = new Error('Invalid property');
    error.statusCode = 400;
    throw error;
  }

  const metadataRaw = rawEvent?.metadata && typeof rawEvent.metadata === 'object' ? rawEvent.metadata : {};
  const metadata = sanitizeAppMetadata({ ...metadataRaw, property });

  // Require core fields so admin graphs can rely on them.
  const required = ['property', 'screen_name', 'flow_stage', 'app_version', 'build_number', 'platform', 'env'];
  for (const k of required) {
    if (metadata[k] === undefined || metadata[k] === null || metadata[k] === '') {
      const error = new Error(`Missing metadata.${k}`);
      error.statusCode = 400;
      throw error;
    }
  }

  const metaSize = safeJsonSize(metadata);
  if (metaSize !== null && metaSize > MAX_METADATA_BYTES) {
    const error = new Error('Metadata too large');
    error.statusCode = 413;
    throw error;
  }

  return {
    eventId,
    eventTime,
    eventType,
    sessionId,
    actorUserId,
    property,
    metadata,
    ...campaignColumnsFromMetadata(metadata),
  };
};

const normalizeEventPayload = ({ body, site, baseContext, rawEvent }) => {
  const eventName = normalizeEventName(rawEvent?.eventName ?? rawEvent?.event);
  if (!eventName || !allowedEvents.has(eventName)) {
    const error = new Error('Invalid eventName');
    error.statusCode = 400;
    throw error;
  }

  const metadata = {
    ...(baseContext || {}),
    ...(body?.metadata && typeof body.metadata === 'object' ? body.metadata : {}),
    ...(rawEvent?.metadata && typeof rawEvent.metadata === 'object' ? rawEvent.metadata : {}),
  };

  // Attach stable context fields into metadata (keeps DB schema stable while expanding signal).
  const anon = clampText(rawEvent?.anonymousId ?? body?.anonymousId, 128);
  const sid = clampText(
    rawEvent?.sessionId ?? rawEvent?.session_id ?? rawEvent?.sid
    ?? body?.sessionId ?? body?.session_id ?? body?.sid,
    128,
  );
  const locale = clampText(rawEvent?.locale ?? body?.locale, 32);
  const routeName = clampText(rawEvent?.routeName ?? body?.routeName, 64);
  const ctaName = clampText(rawEvent?.cta ?? rawEvent?.ctaName ?? rawEvent?.name, 128);
  const formName = clampText(rawEvent?.form ?? rawEvent?.formName, 128);
  const errorMessage = clampText(rawEvent?.message ?? rawEvent?.errorMessage, 512);
  const stack = clampText(rawEvent?.stack, 2048);

  if (anon && typeof metadata.anonymousId !== 'string') metadata.anonymousId = anon;
  if (sid && typeof metadata.sessionId !== 'string') metadata.sessionId = sid;
  if (locale && typeof metadata.locale !== 'string') metadata.locale = locale;
  if (routeName && typeof metadata.routeName !== 'string') metadata.routeName = routeName;
  if (ctaName && typeof metadata.cta !== 'string') metadata.cta = ctaName;
  if (formName && typeof metadata.form !== 'string') metadata.form = formName;
  if (errorMessage && typeof metadata.message !== 'string') metadata.message = errorMessage;
  if (stack && typeof metadata.stack !== 'string') metadata.stack = stack;

  // UTM fields: store in metadata (web_analytics_events has metadata jsonb + GIN index).
  const utmSource = clampText(rawEvent?.utmSource ?? rawEvent?.utm_source ?? body?.utmSource ?? body?.utm_source, 128);
  const utmMedium = clampText(rawEvent?.utmMedium ?? rawEvent?.utm_medium ?? body?.utmMedium ?? body?.utm_medium, 128);
  const utmCampaign = clampText(rawEvent?.utmCampaign ?? rawEvent?.utm_campaign ?? body?.utmCampaign ?? body?.utm_campaign, 128);
  const utmTerm = clampText(rawEvent?.utmTerm ?? rawEvent?.utm_term ?? body?.utmTerm ?? body?.utm_term, 128);
  const utmContent = clampText(rawEvent?.utmContent ?? rawEvent?.utm_content ?? body?.utmContent ?? body?.utm_content, 128);
  if (utmSource && typeof metadata.utmSource !== 'string') metadata.utmSource = utmSource;
  if (utmMedium && typeof metadata.utmMedium !== 'string') metadata.utmMedium = utmMedium;
  if (utmCampaign && typeof metadata.utmCampaign !== 'string') metadata.utmCampaign = utmCampaign;
  if (utmTerm && typeof metadata.utmTerm !== 'string') metadata.utmTerm = utmTerm;
  if (utmContent && typeof metadata.utmContent !== 'string') metadata.utmContent = utmContent;

  const size = safeJsonSize(metadata);
  if (size !== null && size > MAX_METADATA_BYTES) {
    const error = new Error('metadata too large');
    error.statusCode = 413;
    throw error;
  }

  return {
    site,
    eventName,
    eventId: clampText(rawEvent?.eventId ?? rawEvent?.event_id ?? rawEvent?.id ?? body?.eventId ?? body?.event_id, 64),
    path: normalizeWebPath(rawEvent?.path ?? rawEvent?.pathname ?? body?.path ?? body?.pathname),
    referrer: clampText(rawEvent?.referrer ?? body?.referrer, 1024),
    title: clampText(rawEvent?.title ?? body?.title, 256),
    sessionId: sid,
    anonymousId: anon,
    clientTs: clampText(rawEvent?.clientTs ?? rawEvent?.ts ?? body?.clientTs ?? body?.ts, 64),
    ingestFallback: Boolean(rawEvent?.ingestFallback ?? rawEvent?.ingest_fallback ?? body?.ingestFallback ?? body?.ingest_fallback),
    metadata,
  };
};

const parseAllowList = (raw, { defaultValues = [] } = {}) => {
  const value = (raw || '').toString().trim();
  const items = value
    ? value.split(',').map((v) => v.trim()).filter(Boolean)
    : defaultValues;

  return items
    .map((v) => {
      if (v === '*') return '*';
      if (/^https?:\/\//i.test(v)) return v;
      return `https://${v}`;
    })
    .filter(Boolean);
};

const normalizeHostname = (hostname) => {
  const host = (hostname || '').toString().trim().toLowerCase();
  return host.replace(/^www\./, '');
};

const normalizeSiteValue = (value) => {
  const raw = clampText(value, 256);
  if (!raw) return null;
  try {
    if (/^https?:\/\//i.test(raw)) {
      const u = new URL(raw);
      return normalizeHostname(u.hostname);
    }
  } catch (_) {
    // fall through
  }

  const host = raw.replace(/^https?:\/\//i, '').split('/')[0];
  return normalizeHostname(host);
};

const isOriginAllowed = (origin, allowedOrigins) => {
  if (!origin) return true;
  if (allowedOrigins.includes('*')) return true;

  let originUrl;
  try {
    originUrl = new URL(origin);
  } catch (_) {
    return false;
  }

  for (const allowed of allowedOrigins) {
    if (!allowed || allowed === '*') continue;

    let allowedUrl;
    try {
      allowedUrl = new URL(allowed);
    } catch (_) {
      continue;
    }

    if (originUrl.protocol !== allowedUrl.protocol) {
      continue;
    }

    // Treat apex + www as equivalent to avoid accidental production outages
    // when only one variant is present in env allowlists.
    if (normalizeHostname(originUrl.hostname) !== normalizeHostname(allowedUrl.hostname)) {
      continue;
    }

    if (originUrl.port === allowedUrl.port) return true;

    const isLocal =
      allowedUrl.hostname === 'localhost'
      || allowedUrl.hostname === '127.0.0.1'
      || allowedUrl.hostname === '::1';

    // Allow any port for localhost-like origins when the allowlist omits a port.
    if (isLocal && allowedUrl.port === '' && originUrl.port !== '') return true;
  }

  return false;
};

const isProdEnv = String(process.env.NODE_ENV || '').toLowerCase() === 'production';

const allowedOrigins = parseAllowList(process.env.ANALYTICS_ALLOWED_ORIGINS, {
  defaultValues: isProdEnv
    ? [
      'https://kubus.site',
      'https://www.kubus.site',
      'https://art.kubus.site',
      'https://www.art.kubus.site',
      'https://app.kubus.site',
    ]
    : [
      'http://localhost',
      'http://127.0.0.1',
      'http://[::1]',
      'https://kubus.site',
      'https://www.kubus.site',
      'https://art.kubus.site',
      'https://www.art.kubus.site',
      'https://app.kubus.site',
    ],
});

const allowedSites = new Set(
  (process.env.ANALYTICS_ALLOWED_SITES || 'kubus.site,art.kubus.site,app.kubus.site')
    .split(',')
    .map((v) => normalizeSiteValue(v))
    .filter(Boolean),
);

const analyticsLimiter = rateLimit({
  windowMs: parseInt(process.env.ANALYTICS_RATE_LIMIT_WINDOW_MS || '60000', 10),
  max: parseInt(process.env.ANALYTICS_RATE_LIMIT_MAX || '120', 10),
  standardHeaders: true,
  legacyHeaders: false,
});

const shouldSkip = (req) => {
  const dnt = (req.get('dnt') || '').toString();
  const gpc = (req.get('sec-gpc') || '').toString();
  if (dnt === '1' || gpc === '1') return 'privacy';

  const ua = (req.get('user-agent') || '').toString().toLowerCase();
  if (!ua) return 'no_ua';
  if (ua.includes('bot') || ua.includes('crawler') || ua.includes('spider')) return 'bot';

  return null;
};

const handleCollect = asyncHandler(async (req, res) => {
  if (!ANALYTICS_ENABLED) {
    res.status(204).end();
    return;
  }

  const contentLength = parseInt(req.get('content-length') || '0', 10);
  if (Number.isFinite(contentLength) && contentLength > MAX_BODY_BYTES) {
    res.status(413).json({ success: false, error: 'Payload too large' });
    return;
  }

  const skipReason = shouldSkip(req);
  if (skipReason) {
    res.status(204).end();
    return;
  }

  const origin = req.get('origin');
  if (!isOriginAllowed(origin, allowedOrigins)) {
    res.status(403).json({ success: false, error: 'Origin not allowed' });
    return;
  }

  const body = parseBody(req);
  if (!body) {
    res.status(400).json({ success: false, error: 'Invalid payload' });
    return;
  }

  const rawProperty = clampText(body?.property, 128);
  if (rawProperty) {
    const normalizedPropertySite = normalizeSiteValue(rawProperty);
    const isAppProperty = allowedAppProperties.has(rawProperty);
    const isWebProperty = normalizedPropertySite && allowedSites.has(normalizedPropertySite);
    if (!isAppProperty && !isWebProperty) {
      res.status(400).json({ success: false, error: 'Invalid property' });
      return;
    }
  }

  const computedSize = safeJsonSize(body);
  if (computedSize !== null && computedSize > MAX_BODY_BYTES) {
    res.status(413).json({ success: false, error: 'Payload too large' });
    return;
  }

  const normalizedSite = normalizeSiteValue(body?.site);
  if (!normalizedSite || !allowedSites.has(normalizedSite)) {
    res.status(400).json({ success: false, error: 'Invalid site' });
    return;
  }

  const events = Array.isArray(body.events)
    ? body.events
    : Array.isArray(body.batch)
      ? body.batch
      : [body];

  if (!Array.isArray(events) || events.length === 0) {
    res.status(400).json({ success: false, error: 'Missing events' });
    return;
  }

  if (events.length > MAX_EVENTS_PER_BATCH) {
    res.status(413).json({ success: false, error: 'Too many events' });
    return;
  }

  const baseContext = body.context && typeof body.context === 'object' ? body.context : null;

  // Best-effort ingest: one bad event rejects the batch (strict validation).
  const normalized = events.map((rawEvent) => normalizeEventPayload({
    body,
    site: normalizedSite,
    baseContext,
    rawEvent,
  }));

  // Privacy rule: if session identifiers can't be persisted, the client should not send.
  // Defense in depth: ignore any web events that arrive without a session id.
  // Additionally, require a stable UUID eventId for idempotency; events without it are excluded
  // from ingestion so they cannot pollute KPIs or be double-counted across retries/endpoints.
  const filtered = normalized.filter((p) => {
    if (!p.sessionId) return false;
    if (!p.eventId || !UUID_REGEX.test(String(p.eventId))) return false;
    if (p.eventName === 'page_view' && !p.path) return false;
    return true;
  });

  if (filtered.length === 0) {
    res.status(204).end();
    return;
  }

  for (const payload of filtered) {
    await trackWebEvent({ ...payload, req });
  }

  res.status(204).end();
});

const handleAppTelemetry = asyncHandler(async (req, res) => {
  if (!APP_TELEMETRY_ENABLED) {
    res.status(204).end();
    return;
  }

  const contentLength = parseInt(req.get('content-length') || '0', 10);
  if (Number.isFinite(contentLength) && contentLength > MAX_BODY_BYTES) {
    res.status(413).json({ success: false, error: 'Payload too large' });
    return;
  }

  const skipReason = shouldSkip(req);
  if (skipReason === 'privacy' || skipReason === 'bot') {
    res.status(204).end();
    return;
  }

  const body = parseBody(req);
  if (!body) {
    res.status(400).json({ success: false, error: 'Invalid payload' });
    return;
  }

  const computedSize = safeJsonSize(body);
  if (computedSize !== null && computedSize > MAX_BODY_BYTES) {
    res.status(413).json({ success: false, error: 'Payload too large' });
    return;
  }

  const rawEvents = Array.isArray(body.events)
    ? body.events
    : Array.isArray(body.batch)
      ? body.batch
      : Array.isArray(body.data)
        ? body.data
        : [];

  if (!Array.isArray(rawEvents) || rawEvents.length === 0) {
    res.status(400).json({ success: false, error: 'Missing events' });
    return;
  }

  if (rawEvents.length > MAX_EVENTS_PER_BATCH) {
    res.status(413).json({ success: false, error: 'Too many events' });
    return;
  }

  const normalized = rawEvents.map((rawEvent) => normalizeAppEventPayload({ body, rawEvent }));
  if (normalized.length === 0) {
    res.status(204).end();
    return;
  }

  let failed = false;
  for (const event of normalized) {
    try {
      const result = await statsService.trackAnalyticsEvent({
        actorUserId: event.actorUserId,
        property: event.property,
        eventType: event.eventType,
        eventCategory: 'app',
        eventId: event.eventId,
        sessionId: event.sessionId,
        clientType: 'app_client',
        ts: event.eventTime,
        ingestPath: '/analytics',
        skipLegacyInsert: true,
        metadata: event.metadata,
        // Campaign attribution also goes to the first-class columns so the
        // funnel aggregation can group on them without digging through jsonb.
        utmSource: event.utmSource,
        utmMedium: event.utmMedium,
        utmCampaign: event.utmCampaign,
        utmTerm: event.utmTerm,
        utmContent: event.utmContent,
      });
      if (result?.stored === false && !result?.skipped) failed = true;
    } catch (e) {
      failed = true;
      logger.warn('analytics.app ingest failed', { error: e?.message || String(e) });
    }
  }

  if (failed) {
    res.status(503).json({ success: false, error: 'Failed to ingest telemetry' });
    return;
  }

  res.status(204).end();
});

// Legacy endpoint (kept for backwards compatibility).
router.post('/collect', analyticsLimiter, handleCollect);

// Preferred endpoint alias (matches newer client configs).
router.post('/web', analyticsLimiter, handleCollect);

// App client telemetry ingestion (Flutter).
router.post('/app', analyticsLimiter, handleAppTelemetry);

router.get('/health', (req, res) => {
  res.json({ success: true, allowedOrigins, allowedSites: [...allowedSites] });
});

module.exports = router;
